/* ============================================
   ACCORDION COMPONENT
   Collapsible content sections
   ============================================ */

.ds-accordion {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-200);
  overflow: hidden;
}

/* ============================================
   ITEM
   ============================================ */

.ds-accordion__item {
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
}

.ds-accordion__item:last-child {
  border-bottom: none;
}

/* ============================================
   TRIGGER
   ============================================ */

.ds-accordion__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: var(--gap-200);
  padding: var(--padding-400) var(--padding-500);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-accordion__trigger:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-accordion__trigger:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
  border-radius: var(--radius-200);
}

/* ============================================
   TITLE
   ============================================ */

.ds-accordion__title {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

/* ============================================
   ICON
   ============================================ */

.ds-accordion__icon {
  flex-shrink: 0;
  --icon-size: var(--icon-size-500);
  color: var(--color-icon-primary);
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-accordion__item--open .ds-accordion__icon {
  transform: rotate(180deg);
}

/* ============================================
   PANEL
   ============================================ */

.ds-accordion__panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-accordion__item--open .ds-accordion__panel {
  grid-template-rows: 1fr;
}

/* ============================================
   CONTENT
   ============================================ */

.ds-accordion__content {
  overflow: hidden;
  padding: 0 var(--padding-500);
  transition: padding var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-accordion__item--open .ds-accordion__content {
  padding: 0 var(--padding-500) var(--padding-400);
}

.ds-accordion__content p {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
  margin: 0;
}

'use client';

import React, { useState, useCallback } from 'react';
import './Accordion.css';
import '../../fonts/material-symbols.css';

export interface AccordionItem {
  /** Unique identifier */
  id: string;
  /** Header text */
  title: string;
  /** Body content */
  content: React.ReactNode;
}

export interface AccordionProps {
  /** List of accordion items */
  items: AccordionItem[];
  /** Allow multiple items open at once */
  multiple?: boolean;
  /** IDs of initially expanded items */
  defaultExpanded?: string[];
  /** Additional CSS classes */
  className?: string;
}

/**
 * Accordion organises content into collapsible sections.
 * Supports single or multiple open panels.
 */
export const Accordion = ({
  items,
  multiple = false,
  defaultExpanded = [],
  className = '',
}: AccordionProps) => {
  const [expanded, setExpanded] = useState<Set<string>>(new Set(defaultExpanded));
  const baseClass = 'ds-accordion';
  const classes = [baseClass, className].filter(Boolean).join(' ');

  const toggle = useCallback(
    (id: string) => {
      setExpanded((prev) => {
        const next = new Set(prev);
        if (next.has(id)) {
          next.delete(id);
        } else {
          if (!multiple) next.clear();
          next.add(id);
        }
        return next;
      });
    },
    [multiple],
  );

  return (
    <div className={classes}>
      {items.map((item) => {
        const isOpen = expanded.has(item.id);
        return (
          <div
            key={item.id}
            className={`${baseClass}__item${isOpen ? ` ${baseClass}__item--open` : ''}`}
          >
            <button
              type="button"
              className={`${baseClass}__trigger`}
              aria-expanded={isOpen}
              aria-controls={`${baseClass}-panel-${item.id}`}
              id={`${baseClass}-header-${item.id}`}
              onClick={() => toggle(item.id)}
            >
              <span className={`${baseClass}__title`}>{item.title}</span>
              <span
                className={`${baseClass}__icon material-symbols-rounded`}
                aria-hidden="true"
              >
                expand_more
              </span>
            </button>
            <div
              id={`${baseClass}-panel-${item.id}`}
                            aria-labelledby={`${baseClass}-header-${item.id}`}
              className={`${baseClass}__panel`}
            >
              <div className={`${baseClass}__content`}>{item.content}</div>
            </div>
          </div>
        );
      })}
    </div>
  );
};
